SET NOCOUNT ON;
DECLARE @loginA sysname=N'proxima_tenant_a', @loginB sysname=N'proxima_tenant_b';
DECLARE @dbA sysname=N'proxima_tenant_a_db', @dbB sysname=N'proxima_tenant_b_db';
DECLARE @pwA nvarchar(128)=N'$(TENANT_A_PASSWORD)', @pwB nvarchar(128)=N'$(TENANT_B_PASSWORD)';
DECLARE @sql nvarchar(max);
IF DB_ID(@dbA) IS NOT NULL BEGIN SET @sql=N'ALTER DATABASE '+QUOTENAME(@dbA)+N' SET SINGLE_USER WITH ROLLBACK IMMEDIATE; DROP DATABASE '+QUOTENAME(@dbA); EXEC(@sql); END;
IF DB_ID(@dbB) IS NOT NULL BEGIN SET @sql=N'ALTER DATABASE '+QUOTENAME(@dbB)+N' SET SINGLE_USER WITH ROLLBACK IMMEDIATE; DROP DATABASE '+QUOTENAME(@dbB); EXEC(@sql); END;
IF SUSER_ID(@loginA) IS NOT NULL BEGIN SET @sql=N'DROP LOGIN '+QUOTENAME(@loginA); EXEC(@sql); END;
IF SUSER_ID(@loginB) IS NOT NULL BEGIN SET @sql=N'DROP LOGIN '+QUOTENAME(@loginB); EXEC(@sql); END;
SET @sql=N'CREATE DATABASE '+QUOTENAME(@dbA)+N';'; EXEC(@sql);
SET @sql=N'CREATE DATABASE '+QUOTENAME(@dbB)+N';'; EXEC(@sql);
SET @sql=N'CREATE LOGIN '+QUOTENAME(@loginA)+N' WITH PASSWORD='+QUOTENAME(@pwA,'''')+N', DEFAULT_DATABASE='+QUOTENAME(@dbA)+N', CHECK_POLICY=OFF;'; EXEC(@sql);
SET @sql=N'CREATE LOGIN '+QUOTENAME(@loginB)+N' WITH PASSWORD='+QUOTENAME(@pwB,'''')+N', DEFAULT_DATABASE='+QUOTENAME(@dbB)+N', CHECK_POLICY=OFF;'; EXEC(@sql);
SET @sql=N'DENY VIEW ANY DATABASE TO '+QUOTENAME(@loginA)+N'; DENY ALTER ANY LOGIN TO '+QUOTENAME(@loginA)+N';'; EXEC(@sql);
SET @sql=N'DENY VIEW ANY DATABASE TO '+QUOTENAME(@loginB)+N'; DENY ALTER ANY LOGIN TO '+QUOTENAME(@loginB)+N';'; EXEC(@sql);
SET @sql=N'ALTER DATABASE '+QUOTENAME(@dbA)+N' SET TRUSTWORTHY OFF; ALTER DATABASE '+QUOTENAME(@dbA)+N' SET DB_CHAINING OFF; USE '+QUOTENAME(@dbA)+N'; CREATE SCHEMA app AUTHORIZATION dbo; CREATE USER '+QUOTENAME(@loginA)+N' FOR LOGIN '+QUOTENAME(@loginA)+N'; CREATE TABLE app.records(id int NOT NULL PRIMARY KEY,payload nvarchar(100) NOT NULL); INSERT app.records VALUES(1,N''tenant-a''); GRANT SELECT,INSERT,UPDATE,DELETE ON SCHEMA::app TO '+QUOTENAME(@loginA)+N';'; EXEC(@sql);
SET @sql=N'ALTER DATABASE '+QUOTENAME(@dbB)+N' SET TRUSTWORTHY OFF; ALTER DATABASE '+QUOTENAME(@dbB)+N' SET DB_CHAINING OFF; USE '+QUOTENAME(@dbB)+N'; CREATE SCHEMA app AUTHORIZATION dbo; CREATE USER '+QUOTENAME(@loginB)+N' FOR LOGIN '+QUOTENAME(@loginB)+N'; CREATE TABLE app.records(id int NOT NULL PRIMARY KEY,payload nvarchar(100) NOT NULL); INSERT app.records VALUES(1,N''tenant-b''); GRANT SELECT,INSERT,UPDATE,DELETE ON SCHEMA::app TO '+QUOTENAME(@loginB)+N';'; EXEC(@sql);
PRINT 'SQL Server tenant principals and isolated databases provisioned.';
